ALTER TABLE private.demo_requests ADD COLUMN attempts integer NOT NULL DEFAULT 1, ADD COLUMN last_attempt timestamptz NOT NULL DEFAULT now(); CREATE OR REPLACE FUNCTION public.reserve_demo(p_token_hash text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE n integer; BEGIN DELETE FROM private.demo_requests WHERE created_at < now()-interval '24 hours'; INSERT INTO private.demo_requests(token_hash) VALUES(p_token_hash) ON CONFLICT(token_hash) DO UPDATE SET attempts=demo_requests.attempts+1,last_attempt=now() WHERE demo_requests.last_attempt<now()-interval '1 minute' AND demo_requests.attempts<6; GET DIAGNOSTICS n=ROW_COUNT; RETURN n=1; END $$;
